import {STATUSES, STORAGE_KEY, validWorkspace, csv, makeDemo, normalizeAssignments, startPart} from './model.js';
import {shopBoard} from './shop.js';
import {initOnshape} from './onshape-ui.js';
const $ = s => document.querySelector(s);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state, view='parts', editing=null, toastTimer;
let shopMode=false, wakeLock=null, keepAwake=false, previousView='parts';
let pendingStart=null;
try { const saved=localStorage.getItem(STORAGE_KEY); state=saved ? JSON.parse(saved):makeDemo(); if(!validWorkspace(state)) throw new Error('Invalid workspace'); state=normalizeAssignments(state); }
catch { state={version:1,parts:[],materials:[],demo:false}; $('#save-status').textContent='Saved data could not be read. Restore a backup to recover your records.'; }
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function save(next){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));state=next;$('#save-status').textContent='Saved at '+new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});return true;}catch{toast('Could not save. Browser storage may be full or unavailable. Export a backup.');return false;}}
const statusClass = s => ({'In progress':'in-progress','Not started':'not-started',Ready:'ready',Blocked:'blocked',Complete:'complete'}[s]);
const badge=s=>`<span class="status ${statusClass(s)}"><i></i>${escape(s)}</span>`;
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const overdue = p => p.due && p.due < today() && p.status !== 'Complete';
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}):'No deadline';
function filtered(){const term=$('#search').value.trim().toLowerCase();return (view==='inventory'?state.materials:state.parts).filter(r=>Object.values(r).join(' ').toLowerCase().includes(term) && (view==='inventory'||(!$('#status-filter').value||r.status===$('#status-filter').value)&&(!$('#subsystem-filter').value||r.subsystem===$('#subsystem-filter').value)));}
function render(){
 const count=status=>state.parts.filter(p=>p.status===status).length;
 const stats=[['Total parts',state.parts.length,`${state.parts.reduce((sum,p)=>sum+p.quantity,0)} pieces to manufacture`,'▦'],['In progress',count('In progress'),'Moving through the workshop','◷'],['Needs attention',count('Blocked'),`${state.parts.filter(overdue).length} overdue part records`,'⚑'],['Robot-ready',count('Complete'),`${state.parts.length?Math.round(count('Complete')/state.parts.length*100):0}% of part records complete`,'✓']];
 $('#stats').innerHTML=stats.map(([label,value,detail,icon])=>`<div class="stat"><div class="stat-label">${label}</div><span class="stat-icon">${icon}</span><div class="stat-value">${value.toString().padStart(2,'0')}</div><div class="stat-detail">${detail}</div></div>`).join('');
 $('#record-count').textContent=view==='inventory'?state.materials.length:state.parts.length;
 const rows=filtered(); $('#result-count').textContent=`Showing ${rows.length} of ${view==='inventory'?state.materials.length:state.parts.length} ${view==='inventory'?'materials':'parts'}${state.demo?' · Sample workspace':''}`;
 if(shopMode && view==='board'){$('#records').innerHTML=shopBoard(rows,dateLabel);return;}
 if(!rows.length){$('#records').innerHTML='<div class="empty"><h3>No records here yet</h3>Add a record or adjust your search and filters.</div>';return;}
 if(view==='board'){$('#records').innerHTML=`<div class="board">${STATUSES.map(status=>`<section class="board-column"><h3>${status} <span>(${rows.filter(p=>p.status===status).length})</span></h3>${rows.filter(p=>p.status===status).map(p=>`<article class="board-card"><div class="part-number">${escape(p.number||'No part number')}</div><button class="part-name" data-edit="${escape(p.id)}">${escape(p.name)}</button><p>${escape(p.owner||'Unassigned')} · Qty ${p.quantity}<br>${escape(p.process||'No process')}<br>Due ${dateLabel(p.due)}</p><select data-status="${escape(p.id)}" aria-label="Status for ${escape(p.name)}">${STATUSES.map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></article>`).join('')}</section>`).join('')}</div>`;return;}
 if(view==='inventory'){$('#records').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Material / specification</th><th>On hand</th><th>Minimum</th><th>Location</th><th>Stock status</th></tr></thead><tbody>${rows.map(m=>`<tr><td><button class="part-name" data-edit="${escape(m.id)}">${escape(m.name)}</button><div class="part-number">${escape(m.spec)}</div></td><td>${m.stock} ${escape(m.unit)}</td><td>${m.minimum} ${escape(m.unit)}</td><td>${escape(m.location||'Unassigned')}</td><td><span class="status ${m.stock<=m.minimum?'blocked':'complete'}">${m.stock<=m.minimum?'Reorder soon':'In stock'}</span></td></tr>`).join('')}</tbody></table></div>`;return;}
 $('#records').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Part / number</th><th>Subsystem</th><th>Status</th><th>Qty</th><th>Assigned to</th><th>Due date</th><th>Priority</th></tr></thead><tbody>${rows.map(p=>`<tr><td><button class="part-name" data-edit="${escape(p.id)}">${escape(p.name)}</button><div class="part-number">${escape(p.number||'No part number')} · ${escape(p.process||'No process')}</div></td><td><span class="subsystem">${escape(p.subsystem||'Unassigned')}</span></td><td>${badge(p.status)}</td><td>${p.quantity}</td><td><span class="owner"><span class="owner-avatar">${escape((p.owner||'?').split(' ').map(n=>n[0]).join('').slice(0,2))}</span>${escape(p.owner||'Unassigned')}</span></td><td class="${overdue(p)?'overdue':''}">${dateLabel(p.due)}${overdue(p)?' !':''}</td><td><span class="priority ${p.priority==='High'?'high':''}">${p.priority==='High'?'↑ ':''}${escape(p.priority)}</span></td></tr>`).join('')}</tbody></table></div>`;
}
function refreshFilters(){const old=$('#subsystem-filter').value;$('#status-filter').innerHTML='<option value="">All statuses</option>'+STATUSES.map(s=>`<option>${s}</option>`).join('');$('#subsystem-filter').innerHTML='<option value="">All subsystems</option>'+[...new Set(state.parts.map(p=>p.subsystem).filter(Boolean))].sort().map(s=>`<option>${escape(s)}</option>`).join('');$('#subsystem-filter').value=old;}
function switchView(next){view=next;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const inv=view==='inventory';$('#page-title').textContent=inv?'Material inventory':view==='board'?'Production board':'Parts register';$('#page-description').textContent=inv?'Know what is on the shelf before the next cut.':'Every part. Every process. One place to keep the robot moving.';$('#panel-title').firstChild.textContent=inv?'Shop materials ':view==='board'?'Production flow ':'All parts ';$('#panel-subtitle').textContent=inv?'Track stock, storage locations, and reorder levels.':'Your build, from raw stock to robot-ready.';$('#add-record').textContent=inv?'+ Add material':'+ Add part';$('#search').placeholder=inv?'Search materials or storage locations…':'Search parts, numbers, or owners…';$('#search').value='';$('#status-filter').hidden=inv;$('#subsystem-filter').hidden=inv;refreshFilters();render();}
const input=(name,label,type='text',value='',extra='')=>`<label ${name==='notes'||name==='name'?'class="full"':''}>${label}<input name="${name}" type="${type}" value="${escape(value)}" ${extra} maxlength="500"></label>`;
const select=(name,label,options,value)=>`<label>${label}<select name="${name}">${options.map(s=>`<option ${s===value?'selected':''}>${escape(s)}</option>`).join('')}</select></label>`;
function edit(id){editing=id||null;const inv=view==='inventory';const record=(inv?state.materials:state.parts).find(r=>r.id===id)||{};$('#dialog-title').textContent=`${id?'Edit':'Add'} ${inv?'material':'part'}`;$('#delete-record').hidden=!id;$('#form-fields').innerHTML=inv?input('name','Material name','text',record.name,'required')+input('spec','Specification','text',record.spec)+input('location','Storage location','text',record.location)+input('stock','Quantity on hand','number',record.stock??0,'min="0" step="any" required')+input('minimum','Reorder threshold','number',record.minimum??0,'min="0" step="any" required')+input('unit','Unit (sheets, inches, spools…)','text',record.unit,'required'):input('name','Part name','text',record.name,'required')+input('number','Part number','text',record.number)+input('subsystem','Subsystem','text',record.subsystem)+input('quantity','Quantity','number',record.quantity??1,'min="1" step="1" required')+input('assignedTo','Advance assignment (admin, optional)','text',record.assignedTo)+select('status','Manufacturing status',STATUSES,record.status||'Not started')+select('priority','Priority',['Low','Normal','High'],record.priority||'Normal')+input('material','Material','text',record.material)+input('process','Manufacturing process','text',record.process)+input('due','Due date','date',record.due)+input('cad','CAD / drawing URL','url',record.cad)+`<label class="full">Shop notes<textarea name="notes" rows="3" maxlength="10000">${escape(record.notes||'')}</textarea></label>`;$('#record-dialog').showModal();}
$('#record-form').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));Object.keys(values).forEach(k=>values[k]=values[k].trim());values.id=editing||crypto.randomUUID();const existingPart=state.parts.find(p=>p.id===editing);if(view!=='inventory'&&existingPart?.onshape)values.onshape=existingPart.onshape;if(view==='inventory'){values.stock=Number(values.stock);values.minimum=Number(values.minimum);}else {values.quantity=Number(values.quantity);const previous=state.parts.find(p=>p.id===editing);values.owner=values.assignedTo||(previous?.assignedTo?'':previous?.owner||'');if(values.status==='In progress'&&previous?.status!=='In progress'){if(!validWorkspace({...state,parts:[values]})){toast('Check required fields, dates, and quantities.');return;}$('#record-dialog').close();beginWork(values);return;}}const key=view==='inventory'?'materials':'parts';const next={...state,[key]:editing?state[key].map(r=>r.id===editing?values:r):[...state[key],values]};if(!validWorkspace(next)){toast('Check required fields, dates, and quantities.');return;}if(save(next)){$('#record-dialog').close();refreshFilters();render();toast('Record saved');}});
function commitStartedPart(part,worker=''){
 const current=state.parts.find(p=>p.id===part.id);
 // Avoid replacing a newer record if another tab changes it while the picker is open.
 if(pendingStart&&JSON.stringify(current)!==pendingStart.original){toast('This part changed in another tab. Open it again before starting.');$('#start-dialog').close();return;}
 try{const started=startPart(part,worker);const next={...state,parts:current?state.parts.map(p=>p.id===part.id?started:p):[...state.parts,started]};if(save(next)){pendingStart=null;$('#start-dialog').close();refreshFilters();render();toast(`Work started by ${started.owner}`);}}catch(err){toast(err.message);}
}
function beginWork(part){
 if(part.assignedTo?.trim()){commitStartedPart(part);return;}
 pendingStart={part,original:JSON.stringify(state.parts.find(p=>p.id===part.id))};
 $('#start-part-name').textContent=part.name;
 const names=[...new Set(state.parts.flatMap(p=>[p.owner,p.assignedTo]).filter(n=>n?.trim()).map(n=>n.trim()))].sort();
 $('#worker-choices').innerHTML=names.map(name=>`<button type="button" class="secondary" data-worker="${escape(name)}">${escape(name)}</button>`).join('');
 $('#worker-name').value='';$('#start-dialog').showModal();render();
}
function changeStatus(id,status){const part=state.parts.find(p=>p.id===id);if(!part||!STATUSES.includes(status))return;if(status==='In progress'&&part.status!=='In progress'){beginWork(part);return;}if(save({...state,parts:state.parts.map(p=>p.id===id?{...p,status}:p)}))toast('Status updated');render();}
$('#worker-choices').onclick=e=>{const button=e.target.closest('[data-worker]');if(button){$('#worker-name').value=button.dataset.worker;document.querySelectorAll('[data-worker]').forEach(b=>b.classList.toggle('selected',b===button));}};
$('#worker-name').oninput=()=>{document.querySelectorAll('[data-worker]').forEach(b=>b.classList.toggle('selected',b.dataset.worker===$('#worker-name').value));};
$('#start-form').onsubmit=e=>{e.preventDefault();if(pendingStart)commitStartedPart(pendingStart.part,$('#worker-name').value);};
['#cancel-start','#close-start'].forEach(s=>$(s).onclick=()=>$('#start-dialog').close());
$('#start-dialog').addEventListener('close',()=>{pendingStart=null;render();});
$('#delete-record').onclick=()=>{if(!confirm('Delete this record? This cannot be undone.'))return;const key=view==='inventory'?'materials':'parts';if(save({...state,[key]:state[key].filter(r=>r.id!==editing)})){$('#record-dialog').close();refreshFilters();render();toast('Record deleted');}};
$('#records').onclick=e=>{const advance=e.target.closest('[data-advance]');if(advance){changeStatus(advance.dataset.advance,advance.dataset.next);return;}const button=e.target.closest('[data-edit]');if(button)edit(button.dataset.edit);};
$('#records').onchange=e=>{if(e.target.dataset.status){changeStatus(e.target.dataset.status,e.target.value);}};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
$('#add-record').onclick=()=>edit();['#close-dialog','#cancel-dialog'].forEach(s=>$(s).onclick=()=>$('#record-dialog').close());['#search','#status-filter','#subsystem-filter'].forEach(s=>$(s).addEventListener('input',render));
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').onclick=()=>{const keys=view==='inventory'?['name','spec','stock','minimum','unit','location']:['number','name','subsystem','status','quantity','owner','assignedTo','due','priority','material','process','cad','notes'];download('\uFEFF'+csv([keys,...filtered().map(r=>keys.map(k=>r[k]))]),'text/csv;charset=utf-8',`7028-${view}-${today()}.csv`);toast('CSV exported');};
$('#backup').onclick=()=>download(JSON.stringify(state,null,2),'application/json',`7028-workshop-${today()}.json`);
$('#restore').onclick=()=>$('#import-file').click();
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw Error('Backup must be under 5 MB.');const data=JSON.parse(await file.text());if(!validWorkspace(data))throw Error('This file is not a valid 7028 workspace backup.');if(confirm(`Replace this workspace with ${data.parts.length} parts and ${data.materials.length} materials? Back up current data first.`)&&save(normalizeAssignments(data))){refreshFilters();render();toast('Workspace restored');}}catch(err){toast(err instanceof SyntaxError?'The file is not valid JSON.':err.message);}e.target.value='';};
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){try{const next=JSON.parse(e.newValue);if(validWorkspace(next)){state=normalizeAssignments(next);refreshFilters();render();toast('Workspace updated in another tab');}}catch{}}});
refreshFilters();render();
initOnshape({getWorkspace:()=>state,save,onChanged:()=>{refreshFilters();render();},toast});
function updateShopTabs(){document.querySelectorAll('[data-shop-view]').forEach(b=>b.classList.toggle('selected',b.dataset.shopView===view));}
async function releaseWakeLock(){if(wakeLock){await wakeLock.release().catch(()=>{});wakeLock=null;}}
async function requestWakeLock(){if(!keepAwake||!shopMode||document.visibilityState!=='visible')return;try{if(!('wakeLock' in navigator))throw new Error('unsupported');wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null;$('#shop-awake').textContent=keepAwake?'Resume keep awake':'Keep awake';});$('#shop-awake').textContent='Display staying awake';}catch{keepAwake=false;$('#shop-awake').setAttribute('aria-pressed','false');$('#shop-awake').textContent='Keep awake';toast('Keep awake is unavailable. Use the smart board display settings.');}}
function setShopMode(enabled){if(enabled&&!shopMode)previousView=view;shopMode=enabled;document.body.classList.toggle('shop-mode',enabled);$('.shop-controls').hidden=!enabled;const url=new URL(location.href);if(enabled)url.searchParams.set('shop','1');else url.searchParams.delete('shop');history.replaceState(null,'',url);switchView(enabled?'board':previousView);updateShopTabs();if(!enabled){keepAwake=false;$('#shop-awake').setAttribute('aria-pressed','false');$('#shop-awake').textContent='Keep awake';releaseWakeLock();if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}window.scrollTo(0,0);}
$('#enter-shop').onclick=()=>setShopMode(true);
$('#exit-shop').onclick=()=>setShopMode(false);
document.querySelectorAll('[data-shop-view]').forEach(b=>b.onclick=()=>{switchView(b.dataset.shopView);updateShopTabs();window.scrollTo(0,0);});
$('#shop-fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else throw new Error('unsupported');}catch{toast('Fullscreen is unavailable here. Open the app in the smart board browser and use its fullscreen control.');}};
document.addEventListener('fullscreenchange',()=>$('#shop-fullscreen').textContent=document.fullscreenElement?'Leave fullscreen':'Fullscreen');
$('#shop-awake').onclick=async()=>{keepAwake=!keepAwake;$('#shop-awake').setAttribute('aria-pressed',String(keepAwake));if(keepAwake)await requestWakeLock();else{await releaseWakeLock();$('#shop-awake').textContent='Keep awake';}};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&keepAwake&&!wakeLock)requestWakeLock();});
function updateClock(){$('#shop-clock').textContent=new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});}
updateClock();setInterval(updateClock,15000);
if(new URLSearchParams(location.search).get('shop')==='1')setShopMode(true);
if(state.demo){const banner=document.createElement('div');banner.className='demo-banner';banner.innerHTML='<span><strong>Sample workspace</strong> · Explore the workflow with example parts.</span><button>Start empty</button>';$('.stats').before(banner);banner.querySelector('button').onclick=()=>{if(confirm('Remove all sample workspace records and start empty?')){if(save({version:1,demo:false,parts:[],materials:[]})){banner.remove();refreshFilters();render();}}};}
